func TestRecordDutyStatus_ValidTransition(t *testing.T) {
	dummyLogger, _ := logger.New(logger.Config{Level: zapcore.InfoLevel})
	mockRepo := new(MockRepository)
	svc := service.NewComplianceService(dummyLogger, mockRepo)

	ctx := context.Background()
	driverIDStr := uuid.New().String()
	driverID, _ := uuid.Parse(driverIDStr)

	// Mock existing state: Currently OFF_DUTY
	mockRepo.On("GetLatestDutyStatus", ctx, driverID).Return(&models.DriverDutyLog{
		DriverID: driverID,
		Status:   models.DutyStatusOffDuty,
	}, nil)

	// Mock DB save success
	mockRepo.On("RecordDutyStatus", ctx, mock.AnythingOfType("*models.DriverDutyLog")).Return(nil)

	// Action: Transition to ON_DUTY_NOT_DRIVING
	req := &pb.RecordDutyStatusRequest{
		DriverId:  driverIDStr,
		VehicleId: uuid.New().String(),
		Status:    pb.DutyStatus_ON_DUTY_NOT_DRIVING,
	}

	resp, err := svc.RecordDutyStatus(ctx, req)

	// Assert
	assert.NoError(t, err)
	assert.NotNil(t, resp)
	assert.NotNil(t, resp.Log)
	assert.Equal(t, pb.DutyStatus_ON_DUTY_NOT_DRIVING, resp.Log.Status)
	assert.Equal(t, driverIDStr, resp.Log.DriverId)

	mockRepo.AssertExpectations(t)
}

func TestRecordDutyStatus_InvalidTransition(t *testing.T) {
	dummyLogger, _ := logger.New(logger.Config{Level: zapcore.InfoLevel})
	mockRepo := new(MockRepository)
	svc := service.NewComplianceService(dummyLogger, mockRepo)

	ctx := context.Background()
	driverIDStr := uuid.New().String()
	driverID, _ := uuid.Parse(driverIDStr)

	// Mock existing state: Currently DRIVING
	mockRepo.On("GetLatestDutyStatus", ctx, driverID).Return(&models.DriverDutyLog{
		DriverID: driverID,
		Status:   models.DutyStatusDriving,
	}, nil)

	// Action: Transition directly to YARD_MOVES (should be illegal without ON_DUTY first)
	req := &pb.RecordDutyStatusRequest{
		DriverId: driverIDStr,
		Status:   pb.DutyStatus_YARD_MOVES,
	}

	resp, err := svc.RecordDutyStatus(ctx, req)

	// Assert
	assert.ErrorIs(t, err, service.ErrInvalidTransition)
	assert.Nil(t, resp)

	mockRepo.AssertExpectations(t)
}

func TestGetCurrentDutyStatus_NewDriver(t *testing.T) {
	dummyLogger, _ := logger.New(logger.Config{Level: zapcore.InfoLevel})
	mockRepo := new(MockRepository)
	svc := service.NewComplianceService(dummyLogger, mockRepo)

	ctx := context.Background()
	driverIDStr := uuid.New().String()
	driverID, _ := uuid.Parse(driverIDStr)

	// Mock DB returning nothing (new driver)
	mockRepo.On("GetLatestDutyStatus", ctx, driverID).Return((*models.DriverDutyLog)(nil), nil)

	resp, err := svc.GetCurrentDutyStatus(ctx, driverIDStr)

	assert.NoError(t, err)
	assert.NotNil(t, resp)
	assert.Equal(t, pb.DutyStatus_OFF_DUTY, resp.Status) // Defaults to OFF_DUTY

	mockRepo.AssertExpectations(t)
}
